-- Read already captured catalogues once at Enable; never from relaxation.
function Adapter.Describe(planner,options)
    options=options or {}
    local definitions={}
    for _,kind in ipairs({'portal','personal','taxi','scheduled'}) do
        local catalog=planner[kind=='portal' and 'portals' or kind]
        for id,d in pairs(catalog and catalog.byId or {}) do
            local overrides={}
            if kind=='taxi' then overrides=catalog.settings[id] or {}
            elseif kind=='scheduled' then overrides=(options.scheduledOverrides or {})[id] or {} end
            for component,field in pairs(d.totalSeconds==nil and FIELDS[kind] or {}) do
                local default,current
                if kind=='taxi' or kind=='scheduled' then default=d.costs[field] else default=d[field] end
                if kind=='taxi' and component=='ride' then
                    default=(catalog.routes[id] or {}).rideSeconds or default or catalog.defaultRideSeconds
                end
                current=overrides[field] or default
                if kind=='taxi' and component=='ride' and overrides[field]==nil then
                    current=(catalog.routes[id] or {}).rideSeconds or current
                end
                definitions[#definitions+1]={key=kind..'/'..id..'/'..component,
                    kind=kind,id=id,component=component,field=field,defaultSeconds=default,
                    currentSeconds=current,manualSeconds=overrides[field]}
            end
        end
    end
    table.sort(definitions,--[[APR_DIAG]]APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:66:callback#6", --[[/APR_DIAG]]function(a,b)return a.key<b.key end--[[APR_DIAG]])--[[/APR_DIAG]])
    return definitions
end--[[APR_DIAG]]; Adapter.Describe = APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:41:Adapter.Describe#5", Adapter.Describe)--[[/APR_DIAG]]

function Adapter.New(options)
    if type(options)~='table' or (options.store~=nil and type(options.store)~='table') then
        return nil,'invalid_calibration_store'
    end
    local model,reason=Core.New({store=options.store and options.store[NAMESPACE],
        identity=options.identity,definitions=options.definitions})
    if not model then return nil,reason end
    local self=setmetatable({model=model,api=options.api or _G,clock=options.clock,store=options.store,
        definitions={},order={},applied={},routes={},clockReads=0},Session)
    for _,d in ipairs(options.definitions) do
        if not FIELDS[d.kind] or FIELDS[d.kind][d.component]~=d.field or type(d.id)~='string'
            or d.key~=d.kind..'/'..d.id..'/'..d.component then
            return nil,'invalid_calibration_binding'
        end
        local value=d.currentSeconds
        if value==nil then value=d.defaultSeconds end
        if type(value)~='number' or value~=value or value<0 or value==math.huge then return nil,'invalid_calibration_binding' end
        self.definitions[d.key]=Copy(d);self.order[#self.order+1]=d.key;self.applied[d.key]=value
        local route=d.kind..'/'..d.id
        self.routes[route]=self.routes[route] or {}
        self.routes[route][d.component]=d.key
    end
    table.sort(self.order)
    return self
end--[[APR_DIAG]]; Adapter.New = APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:70:Adapter.New#7", Adapter.New)--[[/APR_DIAG]]

