-- One isolated setter payload per changed route. Host batches invalidation/recovery.
function Session:Pending()
    local updates,byRoute={},{}
    for _,key in ipairs(self.order) do
        local d,value=self.definitions[key],self:Get(key)
        if value~=self.applied[key] then
            local name=d.kind..'/'..d.id
            local update=byRoute[name]
            if not update then
                update={kind=d.kind,id=d.id,costs={}}
                updates[#updates+1]=update;byRoute[name]=update
            end
            update.costs[d.field]=value
        end
    end
    return updates
end--[[APR_DIAG]]; Session.Pending = APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:125:Session:Pending#18", Session.Pending)--[[/APR_DIAG]]
function Session:Acknowledge(update)
    if type(update)~='table' or type(update.costs)~='table' or type(update.kind)~='string'
        or type(update.id)~='string' then return nil,'invalid_calibration_update' end
    local keys=self.routes[(update.kind or '')..'/'..(update.id or '')]
    if not keys then return nil,'invalid_calibration_update' end
    local accepted={}
    for field,value in pairs(update.costs) do
        local found
        for _,key in pairs(keys) do
            if self.definitions[key].field==field and value==self:Get(key) then found=key end
        end
        if not found then return nil,'stale_calibration_update' end
        accepted[found]=value
    end
    for key,value in pairs(accepted) do self.applied[key]=value end
    return true
end--[[APR_DIAG]]; Session.Acknowledge = APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:141:Session:Acknowledge#19", Session.Acknowledge)--[[/APR_DIAG]]
function Session:Export(root)
    if root==nil then root=self.store end
    if root~=nil and type(root)~='table' then return nil,'invalid_calibration_store' end
    local value,reason=self.model:Export(root and root[NAMESPACE])
    if reason then return nil,reason end
    local result=Copy(root)
    result[NAMESPACE]=value
    return result
end--[[APR_DIAG]]; Session.Export = APRTrace("APR-Core/features/navigation/NavigationV2Calibration.lua:158:Session:Export#20", Session.Export)--[[/APR_DIAG]]

